    // Linear-interpolates between two colors for smooth hover-fade animations. progress 0 = a, 1 = b.
    private static Color lerpColor(Color a, Color b, float progress) {
        progress = Math.max(0f, Math.min(1f, progress));
        int r = (int) (a.getRed() + (b.getRed() - a.getRed()) * progress);
        int g = (int) (a.getGreen() + (b.getGreen() - a.getGreen()) * progress);
        int bl = (int) (a.getBlue() + (b.getBlue() - a.getBlue()) * progress);
        return new Color(r, g, bl);
    }

    // Reusable rounded-corner line border for Stage 1's geometry pass. Mirrors BorderFactory.createLineBorder's
// role but draws rounded corners. Use createRoundedLineBorder(color, thickness, radius) as a drop-in
// replacement where a component's role calls for subtle rounding (see RADIUS_* constants above).
    private static javax.swing.border.Border createRoundedLineBorder(Color color, int thickness, int radius)
    {
        return new javax.swing.border.AbstractBorder()
        {
            @Override
            public void paintBorder(Component c, java.awt.Graphics g, int x, int y, int width, int height)
            {
                java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(color);
                g2.setStroke(new java.awt.BasicStroke(thickness));
                int inset = thickness / 2;
                g2.drawRoundRect(x + inset, y + inset, width - thickness, height - thickness, radius * 2, radius * 2);
                g2.dispose();
            }

            @Override
            public java.awt.Insets getBorderInsets(Component c)
            {
                return new java.awt.Insets(thickness, thickness, thickness, thickness);
            }

            @Override
            public java.awt.Insets getBorderInsets(Component c, java.awt.Insets insets)
            {
                insets.left = insets.top = insets.right = insets.bottom = thickness;
                return insets;
            }
        };
    }

    // Reusable marquee-scrolling label for Stage 1's truncated-name UX pass. Behaves exactly like a
// normal truncating JLabel until hovered; if the text doesn't fit, hovering for ~1s starts a slow
// horizontal scroll to reveal the full text, pausing briefly at the end before looping. Call
// startHoverDelay() on mouseEntered and stopAll() on mouseExited/click.
    private static class MarqueeLabel extends JComponent {
        private String fullText;
        private Color color;
        private Font labelFont;
        private int offset = 0;
        private javax.swing.Timer delayTimer;
        private javax.swing.Timer scrollTimer;
        private boolean scrolling = false;
        private boolean paused = false;
        private int pauseTicksRemaining = 0;
        private static final int TICK_MS = 30;
        private static final int DELAY_MS = 1000;
        private static final int END_PAUSE_TICKS = 80;
        private static final int START_PAUSE_TICKS = 40;

        private final int targetWidth;
        private final int targetHeight;

        MarqueeLabel(String text, Color color, Font font, int targetWidth, int targetHeight) {
            this.fullText = text;
            this.color = color;
            this.labelFont = font;
            this.targetWidth = targetWidth;
            this.targetHeight = targetHeight;
            setOpaque(false);
        }

        @Override
        public Dimension getMaximumSize() {
            return new Dimension(targetWidth, targetHeight);
        }

        @Override
        public Dimension getPreferredSize() {
            return new Dimension(targetWidth, targetHeight);
        }

        @Override
        public Dimension getMinimumSize() {
            return new Dimension(0, targetHeight);
        }

        private boolean isTruncated() {
            FontMetrics fm = getFontMetrics(labelFont);
            return fm.stringWidth(fullText) > getWidth();
        }

        void startHoverDelay() {
            stopAll();
            if (!isTruncated()) return;
            delayTimer = new javax.swing.Timer(DELAY_MS, e -> startScrolling());
            delayTimer.setRepeats(false);
            delayTimer.start();
        }

        private void startScrolling() {
            scrolling = true;
            offset = 0;
            paused = true;
            pauseTicksRemaining = START_PAUSE_TICKS;
            scrollTimer = new javax.swing.Timer(TICK_MS, e -> tick());
            scrollTimer.start();
        }

        private void tick() {
            FontMetrics fm = getFontMetrics(labelFont);
            int maxOffset = Math.max(0, fm.stringWidth(fullText) - getWidth());
            if (paused) {
                pauseTicksRemaining--;
                if (pauseTicksRemaining <= 0) {
                    if (offset >= maxOffset) {
                        // end pause just finished - reset to start, then pause there too
                        offset = 0;
                        pauseTicksRemaining = START_PAUSE_TICKS;
                    } else {
                        // start pause just finished - begin scrolling
                        paused = false;
                    }
                }
            } else {
                offset += 1;
                if (offset >= maxOffset) {
                    offset = maxOffset;
                    paused = true;
                    pauseTicksRemaining = END_PAUSE_TICKS;
                }
            }
            repaint();
        }

        void stopAll() {
            if (delayTimer != null) { delayTimer.stop(); delayTimer = null; }
            if (scrollTimer != null) { scrollTimer.stop(); scrollTimer = null; }
            scrolling = false;
            paused = false;
            offset = 0;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_LCD_HRGB);
            g2.setFont(labelFont);
            g2.setColor(color);
            FontMetrics fm = g2.getFontMetrics();
            int y = (getHeight() - fm.getHeight()) / 2 + fm.getAscent();
            if (scrolling) {
                g2.setClip(0, 0, getWidth(), getHeight());
                g2.drawString(fullText, -offset, y);
            } else {
                String display = fullText;
                if (fm.stringWidth(display) > getWidth()) {
                    while (display.length() > 0 && fm.stringWidth(display + "...") > getWidth()) {
                        display = display.substring(0, display.length() - 1);
                    }
                    display += "...";
                }
                g2.drawString(display, 0, y);
            }
            g2.dispose();
        }
    }

