    public void updateBankItems(java.util.List<String> items, java.util.Map<String, Integer> quantities, long bankOnlyValue, long totalWealthValue)
    {
        java.util.Set<String> newItemSet = new java.util.HashSet<>(items);
        java.util.Set<String> oldItemSet = new java.util.HashSet<>(this.bankItems);
        // track items that were displayed but are now gone from bank
        for (String name : displayedGainersLosers) {
            boolean inNew = newItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0]));
            boolean inOld = oldItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0]));
            if (inOld && !inNew)
                removedFromDisplay.add(name);
        }
        // rebuild if displayed item changed, or if a previously-removed displayed item returned
        boolean displayedItemChanged = displayedGainersLosers.stream().anyMatch(name -> {
            boolean inNew = newItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0]));
            boolean inOld = oldItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0]));
            int newQty = quantities.getOrDefault(name, quantities.entrySet().stream().filter(e -> e.getKey().startsWith(name + "|")).mapToInt(java.util.Map.Entry::getValue).sum());
            int oldQty = this.bankQuantities.getOrDefault(name, this.bankQuantities.entrySet().stream().filter(e -> e.getKey().startsWith(name + "|")).mapToInt(java.util.Map.Entry::getValue).sum());
            return inNew != inOld || newQty != oldQty;
        });
        boolean removedItemReturned = removedFromDisplay.stream().anyMatch(name ->
                newItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0])));
        boolean itemListChanged = displayedGainersLosers.isEmpty() || displayedItemChanged || removedItemReturned;
        if (removedItemReturned) removedFromDisplay.removeIf(name ->
                newItemSet.stream().anyMatch(s -> s.equals(name) || s.startsWith(name + "|") || name.startsWith(s.split("\\|")[0])));
        this.bankItems.clear();
        this.bankItems.addAll(items);
        this.bankQuantities.clear();
        this.bankQuantities.putAll(quantities);
        this.totalBankValue = bankOnlyValue;
        this.totalWealthValue = totalWealthValue;
// update bank value label in place if visible
        if (liveBankValueLabel != null && activeTab == 2) {
            boolean bankHidden = plugin.isBankValueHidden();
            long displayVal = showTotalWealth ? totalWealthValue : bankOnlyValue;
            String bankValueStr = displayVal == 0 ? "No bank data" : formatFullPrice(String.valueOf(displayVal)) + " gp";
            String heroText = bankHidden ? "Click to reveal" : bankValueStr;
            liveBankValueLabel.setText(heroText);
            liveBankValueLabel.setForeground(bankHidden ? TEXT_DIM : PRICE_GOLD);
        }
        saveBankData();
        if (activeTab == 2)
        {
            if (itemListChanged)
            {
                // Hide the variant popup before rebuilding - its anchor row may be about to be
                // removed/replaced, and mouseExited never fires when a component is destroyed out
                // from under the cursor rather than the mouse actually leaving it. Also suppress new
                // popup activation briefly afterward, since Swing may fire a stray mouseEntered on
                // whatever new row reflows under a stationary cursor during/right after the rebuild.
                hideVariantPopup();
                suppressVariantPopupActivation = true;
                // close any open floating stats panel before rebuilding
                if (activeStatsFloatPanel != null && activeStatsLayeredPane != null) {
                    activeStatsLayeredPane.remove(activeStatsFloatPanel);
                    activeStatsLayeredPane.repaint();
                    activeStatsFloatPanel = null;
                    activeStatsLayeredPane = null;
                }
                isRefreshing = true;
                showTab(2);
                isRefreshing = false;
                javax.swing.Timer suppressReleaseTimer = new javax.swing.Timer(200, e3 -> suppressVariantPopupActivation = false);
                suppressReleaseTimer.setRepeats(false);
                suppressReleaseTimer.start();
                if (bankReopenAction != null)
                {
                    javax.swing.Timer t = new javax.swing.Timer(150, e2 -> bankReopenAction.run());
                    t.setRepeats(false);
                    t.start();
                }
            }
        }
    }

