    // Warms variantPopupNameCache with display names for every known variant ID, resolved on the client thread.
    // Called once after itemVariantMap is populated, so popup hover never needs a live getItemComposition() call.
    private void warmVariantPopupNameCache()
    {
        java.util.Set<Integer> variantIds = new java.util.HashSet<>(itemVariantMap.keySet());
        plugin.resolveItemNamesOnClientThread(variantIds, results -> {
            variantPopupNameCache.putAll(results);
        });
    }

    // Lazily builds (once) and returns the reverse grouping: tradeable base ID -> raw list of variant IDs mapped to it.
// Derived entirely from itemVariantMap. Not deduplicated by name - that happens at render time.
    private java.util.Map<Integer, java.util.List<Integer>> getBaseToVariantIds()
    {
        if (baseToVariantIdsCache == null)
        {
            baseToVariantIdsCache = new java.util.HashMap<>();
            for (java.util.Map.Entry<Integer, Integer> entry : itemVariantMap.entrySet())
            {
                int variantId = entry.getKey();
                int baseId = entry.getValue();
                baseToVariantIdsCache
                        .computeIfAbsent(baseId, k -> new java.util.ArrayList<>())
                        .add(variantId);
            }
        }
        return baseToVariantIdsCache;
    }

    // Resolves an item ID to its RuneLite display name, cached by ID.
// Used for popup name resolution only - separate from the tradeable-only name maps (nameToId/idToName).
    private String getVariantPopupName(int itemId)
    {
        // Cache-only: never calls getItemComposition() directly, since that must run on RuneLite's client
        // thread and this may be called from Swing event handlers. Cache is warmed by warmVariantPopupNameCache().
        return variantPopupNameCache.get(itemId);
    }

    // Resolves a representative variant ID for a given tradeable base + hovered display name, for icon/popup display only.
// Multiple variant IDs may share the same display name (e.g. charged/uncharged states) - any matching ID is treated
// as equivalent for display purposes. Never use the returned ID for pricing, limits, or identity-sensitive logic.
    private Integer resolveVariantDisplayId(int baseId, String displayName)
    {
        if (displayName == null || displayName.trim().isEmpty())
        {
            return null;
        }
        String normalizedName = displayName.trim().toLowerCase(java.util.Locale.ROOT);
        String cacheKey = baseId + "|" + normalizedName;
        Integer cached = variantDisplayIdCache.get(cacheKey);
        if (cached != null)
        {
            return cached;
        }
        java.util.List<Integer> variants = getBaseToVariantIds().get(baseId);
        if (variants == null)
        {
            return null;
        }
        for (Integer variantId : variants)
        {
            String candidateName = getVariantPopupName(variantId);
            if (candidateName != null && candidateName.equalsIgnoreCase(displayName))
            {
                variantDisplayIdCache.put(cacheKey, variantId);
                return variantId;
            }
        }
        return null;
    }

    // Builds a deduplicated list of "other variant" display names sharing the same tradeable base,
// excluding the hovered variant's own display name. Presentation only - names come from getVariantPopupName().
    private java.util.List<String> getOtherVariantNames(int baseId, String hoveredDisplayName)
    {
        java.util.List<String> result = new java.util.ArrayList<>();
        java.util.List<Integer> variants = getBaseToVariantIds().get(baseId);
        if (variants == null)
        {
            return result;
        }
        String normalizedHovered = hoveredDisplayName != null
                ? hoveredDisplayName.trim().toLowerCase(java.util.Locale.ROOT)
                : null;
        java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<>();
        for (Integer variantId : variants)
        {
            String name = getVariantPopupName(variantId);
            if (name == null)
            {
                continue;
            }
            String normalizedName = name.trim().toLowerCase(java.util.Locale.ROOT);
            if (normalizedName.equals(normalizedHovered))
            {
                continue;
            }
            if (seen.add(normalizedName))
            {
                result.add(name);
            }
        }
        return result;
    }

    // Quietly warms iconCache for an item ID in the background, with no UI creation. Used to prewarm
    // icons for owned variants/bases during the bank scan, so the popup's first hover can normally
    // read from the cache immediately instead of falling back to createPopupIconLabel()'s async path.
    private void prewarmPopupIcon(int itemId)
    {
        if (iconCache.containsKey(itemId))
        {
            return;
        }
        new Thread(() -> {
            java.awt.image.BufferedImage img = plugin.getItemManager().getImage(itemId);
            if (img != null)
            {
                iconCache.put(itemId, new ImageIcon(img));
            }
        }).start();
    }

    // Creates a fixed-size icon label for the variant popup, loading synchronously from iconCache if available,
// otherwise showing blank and loading asynchronously. The completion callback only updates this specific label
// (checked for displayability) so a late-arriving load for a since-replaced popup row cannot corrupt the popup.
    private JLabel createPopupIconLabel(int itemId)
    {
        JLabel label = new JLabel();
        label.setPreferredSize(new Dimension(32, 32));
        label.setHorizontalAlignment(SwingConstants.CENTER);
        ImageIcon cached = iconCache.get(itemId);
        if (cached != null)
        {
            label.setIcon(cached);
            return label;
        }
        new Thread(() -> {
            java.awt.image.BufferedImage img = plugin.getItemManager().getImage(itemId);
            if (img != null)
            {
                ImageIcon icon = new ImageIcon(img);
                iconCache.put(itemId, icon);
                javax.swing.SwingUtilities.invokeLater(() -> {
                    if (label.isDisplayable())
                    {
                        label.setIcon(icon);
                        label.revalidate();
                        label.repaint();
                        // Propagate the refresh up through parents, then force the heavyweight popup
                        // window itself to repack/repaint - a label-level repaint alone doesn't always
                        // reach the JWindow's actual rendered pixels on the first async load.
                        java.awt.Container parent = label.getParent();
                        while (parent != null)
                        {
                            parent.revalidate();
                            parent.repaint();
                            parent = parent.getParent();
                        }
                        if (variantPopupWindow != null && variantPopupWindow.isVisible())
                        {
                            variantPopupWindow.pack();
                            variantPopupWindow.repaint();
                        }
                    }
                });
            }
        }).start();
        return label;
    }

    // Builds and shows the improved variant info popup, ownership-first: shows only the variants the
// player actually owns for this tradeable base. baseId = tradeable base item ID (source for price/
// limit/icon). ownedVariantNames = all owned untradeable variant names for this base (from
// variantOwned in buildBankItemBlock). Scoped to variant rows only.
    private void showVariantPopup(JComponent anchor, int baseId, java.util.List<String> ownedVariantNames)
    {
        if (variantPopupWindow == null)
        {
            variantPopupWindow = new javax.swing.JWindow();
            variantPopupWindow.setType(java.awt.Window.Type.POPUP);
            variantPopupWindow.setFocusableWindowState(false);
        }

        String baseName = getItemName(baseId);
        if (baseName == null)
        {
            baseName = "Unknown item";
        }
        PriceData basePriceData = priceCache.get(baseId);
        long basePrice = basePriceData != null ? basePriceData.getMid() : 0;
        Integer baseLimit = itemLimits.get(baseId);

        // Header rule: single owned variant -> show its literal name. Multiple owned -> show the base name,
        // since there's no single correct "hovered" item to feature when several variants are owned at once.
        String headerText = (ownedVariantNames != null && ownedVariantNames.size() == 1)
                ? ownedVariantNames.get(0)
                : baseName;

        final int popupCornerRadius = 10;
        JPanel content = new JPanel() {
            @Override
            protected void paintComponent(java.awt.Graphics g) {
                java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(getBackground());
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), popupCornerRadius, popupCornerRadius);
                g2.dispose();
                super.paintComponent(g);
            }
            @Override
            protected void paintBorder(java.awt.Graphics g) {
                java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(VARIANT_POPUP_BORDER);
                g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, popupCornerRadius, popupCornerRadius);
                g2.dispose();
            }
        };
        content.setOpaque(false);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(VARIANT_POPUP_BG);
        content.setBorder(new EmptyBorder(10, 12, 10, 12));

// Header: item/base name — never truncates in practice, plain label
        JLabel headerName = new JLabel(headerText);
        headerName.setForeground(TEXT_PRIMARY);
        headerName.setFont(new Font("Monospaced", Font.BOLD, 13));
        headerName.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel headerBadge = new JLabel("Untradeable Variant");
