    public void checkPriceAlerts()
    {
        for (java.util.Map.Entry<Integer, String> alertEntry : new java.util.HashMap<>(priceAlerts).entrySet())
        {
            int alertId = alertEntry.getKey();
            String alertValue = alertEntry.getValue();
            PriceData alertPd = priceCache.get(alertId);
            if (alertPd == null) continue;
            long currentPrice = alertPd.getMid();
            String[] parts = alertValue.split(":");
            if (parts.length < 2) continue;
            boolean isAbove = parts[0].equals("above");
            long targetPrice = 0;
            try { targetPrice = Long.parseLong(parts[1]); } catch (NumberFormatException e) { continue; }
            boolean triggered = isAbove ? currentPrice >= targetPrice : currentPrice <= targetPrice;
            if (triggered)
            {
                String alertItemName = idToName.getOrDefault(alertId, "Unknown");
                final String finalName = alertItemName;
                final long finalPrice = currentPrice;
                final boolean finalIsAbove = isAbove;
                final long finalTarget = targetPrice;
                plugin.fireAlert(finalName, finalPrice, finalIsAbove, finalTarget);
                priceAlerts.remove(alertId);
                savePriceAlerts();
                firedAlerts.add(alertId);
                alertFiredTimes.put(alertId, System.currentTimeMillis());
                firedAlertTargets.put(alertId, targetPrice);
                firedAlertDirections.put(alertId, isAbove);
                plugin.updateAlertInfoBoxes();
                javax.swing.Timer delayedUpdate = new javax.swing.Timer(100, e -> plugin.updateAlertInfoBoxes());
                delayedUpdate.setRepeats(false);
                delayedUpdate.start();
            }
        }
    }

    private void savePriceAlerts()
    {
        StringBuilder sb = new StringBuilder();
        for (java.util.Map.Entry<Integer, String> entry : priceAlerts.entrySet())
        {
            if (sb.length() > 0) sb.append(",");
            sb.append(entry.getKey()).append(":").append(entry.getValue());
        }
        plugin.saveConfig("priceAlerts", sb.toString());
        plugin.updateAlertInfoBoxes();
    }

    private void loadPriceAlerts()
    {
        priceAlerts.clear();
        String saved = plugin.loadConfig("priceAlerts");
        if (saved == null || saved.isEmpty()) return;
        for (String entry : saved.split(","))
        {
            String[] parts = entry.split(":", 2);
            if (parts.length == 2)
            {
                try {
                    int id = Integer.parseInt(parts[0]);
                    priceAlerts.put(id, parts[1]);
                } catch (NumberFormatException e) { }
            }
        }
    }

    private void startLiveTimer()
    {
        liveTimer = new javax.swing.Timer(1000, e ->
        {
            secondsSinceRefresh++;
            if (timerLabel != null)
            {
                String text;
                if (secondsSinceRefresh < 60)
                    text = secondsSinceRefresh + "s ago";
                else if (secondsSinceRefresh < 3600)
                    text = (secondsSinceRefresh / 60) + "m ago";
                else
                    text = (secondsSinceRefresh / 3600) + "h ago";
                timerLabel.setText(text);
            }
        });
        liveTimer.start();
    }

