        footerBar.add(attribution, BorderLayout.CENTER);
        attribution.setHorizontalAlignment(SwingConstants.RIGHT);

        // Hover listener to show/hide slide panel
        MouseAdapter footerHover = new MouseAdapter() {
            public void mouseEntered(MouseEvent e) {
                slidePanel.setVisible(true);
                final int targetH = 50;
                final int[] curH = {0};
                slidePanel.setPreferredSize(new Dimension(230, 0));
                slidePanel.revalidate();
                javax.swing.Timer openTimer = new javax.swing.Timer(12, null);
                openTimer.addActionListener(ev -> {
                    curH[0] = Math.min(curH[0] + 8, targetH);
                    slidePanel.setPreferredSize(new Dimension(230, curH[0]));
                    slidePanel.revalidate();
                    slidePanel.repaint();
                    if (curH[0] >= targetH) {
                        slidePanel.setPreferredSize(new Dimension(230, targetH));
                        ((javax.swing.Timer)ev.getSource()).stop();
                    }
                });
                openTimer.start();
            }
            public void mouseExited(MouseEvent e) {
                java.awt.Point p = e.getPoint();
                java.awt.Rectangle footerBounds = footerBar.getBounds();
                java.awt.Rectangle slideBounds = slidePanel.getBounds();
                if (!footerBounds.contains(p) && !slideBounds.contains(SwingUtilities.convertPoint(footerBar, p, slidePanel.getParent()))) {
                    final int[] curH = {slidePanel.getPreferredSize().height};
                    javax.swing.Timer closeTimer = new javax.swing.Timer(12, null);
                    closeTimer.addActionListener(ev -> {
                        curH[0] = Math.max(curH[0] - 8, 0);
                        slidePanel.setPreferredSize(new Dimension(230, curH[0]));
                        slidePanel.revalidate();
                        slidePanel.repaint();
                        if (curH[0] <= 0) {
                            slidePanel.setVisible(false);
                            ((javax.swing.Timer)ev.getSource()).stop();
                        }
                    });
                    closeTimer.start();
                }
            }
        };

        footerBar.addMouseListener(footerHover);
        slidePanel.addMouseListener(new MouseAdapter() {
            public void mouseExited(MouseEvent e) {
                java.awt.Point p = SwingUtilities.convertPoint(slidePanel, e.getPoint(), slidePanel.getParent());
                java.awt.Rectangle footerBounds = footerBar.getBounds();
                java.awt.Rectangle slideBounds = slidePanel.getBounds();
                if (!footerBounds.contains(p) && !slideBounds.contains(p)) {
                    slidePanel.setVisible(false);
                    slidePanel.revalidate();
                    slidePanel.repaint();
                }
            }
        });

        JPanel footerContainer = new JPanel(new BorderLayout());
        footerContainer.setBackground(new Color(20, 18, 19));
        footerContainer.add(slidePanel, BorderLayout.NORTH);
        footerContainer.add(footerBar, BorderLayout.SOUTH);

        add(wrapper, BorderLayout.CENTER);
        getWrappedPanel().add(footerContainer, BorderLayout.SOUTH);
    }

    private JPanel buildHeader()
    {
        JPanel headerWrap = new JPanel(new BorderLayout());
        headerWrap.setBackground(BG_DARK);

        JPanel titleRow = new JPanel(new BorderLayout());
        titleRow.setBackground(BG_HEADER);
        titleRow.setBorder(new EmptyBorder(6, 8, 6, 8));

        JLabel title = new JLabel("GE Companion");
        title.setForeground(GOLD);
        title.setFont(new Font("Monospaced", Font.PLAIN, FONT_TITLE));
        titleRow.add(title, BorderLayout.WEST);

        JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        rightPanel.setBackground(BG_HEADER);

        JLabel liveDot = new JLabel("●");
        liveDot.setForeground(LIVE_GREEN);
        liveDot.setToolTipText("Live — prices auto-refresh every 60 seconds");
// pulsing animation
        final float[] phase = {0f};
        javax.swing.Timer pulseTimer = new javax.swing.Timer(50, ev -> {
            phase[0] += 0.12f;
            float brightness = (float)(0.5 + 0.5 * Math.sin(phase[0]));
            int r = (int)(30 + brightness * (74 - 30));
            int g = (int)(80 + brightness * (154 - 80));
            int b = (int)(20 + brightness * (48 - 20));
            liveDot.setForeground(new Color(r, g, b));
        });
        pulseTimer.start();
        liveDot.setFont(new Font("Monospaced", Font.PLAIN, FONT_STAT_LABEL));

        timerLabel = new JLabel("0s ago");
        timerLabel.setForeground(TAB_INACTIVE);
        timerLabel.setFont(new Font("Monospaced", Font.PLAIN, FONT_META));
        timerLabel.setToolTipText("Time since last price refresh — prices auto-refresh every 60 seconds");
        JLabel timer = timerLabel;

        JLabel refresh = new JLabel("↻");
        refresh.setForeground(TAB_INACTIVE);
        refresh.setFont(new Font("Monospaced", Font.PLAIN, FONT_REFRESH));
        refresh.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        final float[] refreshHoverProgress = {0f};
        final javax.swing.Timer[] refreshAnimTimer = {null};
        refresh.addMouseListener(new MouseAdapter()
        {
            public void mouseEntered(MouseEvent e) {
                if (refreshAnimTimer[0] != null) refreshAnimTimer[0].stop();
                refreshAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                    refreshHoverProgress[0] = Math.min(1f, refreshHoverProgress[0] + 0.15f);
                    refresh.setForeground(lerpColor(TAB_INACTIVE, GOLD, refreshHoverProgress[0]));
                    if (refreshHoverProgress[0] >= 1f) refreshAnimTimer[0].stop();
                });
                refreshAnimTimer[0].start();
            }
            public void mouseExited(MouseEvent e) {
                if (refreshAnimTimer[0] != null) refreshAnimTimer[0].stop();
                refreshAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                    refreshHoverProgress[0] = Math.max(0f, refreshHoverProgress[0] - 0.15f);
                    refresh.setForeground(lerpColor(TAB_INACTIVE, GOLD, refreshHoverProgress[0]));
                    if (refreshHoverProgress[0] <= 0f) refreshAnimTimer[0].stop();
                });
                refreshAnimTimer[0].start();
            }
            public void mouseClicked(MouseEvent e)
            {
                refresh.setForeground(GOLD);
                new Thread(() -> plugin.fetchPrices()).start();
            }
        });

        rightPanel.add(liveDot);
        rightPanel.add(timer);
        rightPanel.add(refresh);
        titleRow.add(rightPanel, BorderLayout.EAST);

        JPanel tabRow = new JPanel(new GridLayout(1, 3));
        tabRow.setBackground(BG_HEADER);
        tabRow.setBorder(new MatteBorder(0, 0, 1, 0, new Color(42, 37, 40)));

        String[] tabNames = {"Watchlist", "Search", "Bank"};
        for (int i = 0; i < 3; i++)
        {
            final int idx = i;
            JLabel tab = new JLabel(tabNames[i], SwingConstants.CENTER);
            tab.setFont(new Font("Monospaced", Font.PLAIN, FONT_TAB));
            tab.setBorder(new EmptyBorder(5, 0, 5, 0));
            tab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            updateTabStyle(tab, i == activeTab);
            final float[] tabHoverProgress = {0f};
            final javax.swing.Timer[] tabAnimTimer = {null};
            tab.addMouseListener(new MouseAdapter()
            {
                public void mouseClicked(MouseEvent e)
                {
                    if (tabAnimTimer[0] != null) tabAnimTimer[0].stop();
                    // Collapse bank metadata when leaving the bank tab
                    if (activeTab == 2 && idx != 2 && bankMetadataExpanded) {
                        bankMetadataExpanded = false;
                    }
                    // Close floating stats panel when switching tabs
                    if (activeStatsFloatPanel != null && activeStatsLayeredPane != null) {
                        activeStatsLayeredPane.remove(activeStatsFloatPanel);
                        activeStatsLayeredPane.repaint();
                        activeStatsFloatPanel = null;
                        activeStatsLayeredPane = null;
                    }
                    activeTab = idx;
                    for (int j = 0; j < 3; j++)
                        updateTabStyle(tabLabels[j], j == idx);
                    showTab(idx);
                }
                public void mouseEntered(MouseEvent e)
                {
                    if (idx != activeTab) {
                        if (tabAnimTimer[0] != null) tabAnimTimer[0].stop();
                        tabAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                            if (idx == activeTab) { tabAnimTimer[0].stop(); return; }
                            tabHoverProgress[0] = Math.min(1f, tabHoverProgress[0] + 0.15f);
                            tab.setForeground(lerpColor(TAB_INACTIVE, TEXT_PRIMARY, tabHoverProgress[0]));
                            if (tabHoverProgress[0] >= 1f) tabAnimTimer[0].stop();
                        });
                        tabAnimTimer[0].start();
                    }
                }
                public void mouseExited(MouseEvent e)
                {
                    if (idx != activeTab) {
                        if (tabAnimTimer[0] != null) tabAnimTimer[0].stop();
                        tabAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                            if (idx == activeTab) { tabAnimTimer[0].stop(); return; }
                            tabHoverProgress[0] = Math.max(0f, tabHoverProgress[0] - 0.15f);
                            tab.setForeground(lerpColor(TAB_INACTIVE, TEXT_PRIMARY, tabHoverProgress[0]));
                            if (tabHoverProgress[0] <= 0f) tabAnimTimer[0].stop();
                        });
                        tabAnimTimer[0].start();
                    }
                }
            });
            tabLabels[i] = tab;
            tabRow.add(tab);
        }

        headerWrap.add(titleRow, BorderLayout.NORTH);
        headerWrap.add(tabRow, BorderLayout.SOUTH);
        return headerWrap;
    }

    private void updateTabStyle(JLabel tab, boolean active)
    {
        if (active)
        {
            tab.setForeground(GOLD);
            tab.setBorder(new MatteBorder(0, 0, 2, 0, GOLD));
        }
        else
        {
            tab.setForeground(TAB_INACTIVE);
            tab.setBorder(new EmptyBorder(0, 0, 2, 0));
        }
    }

    public void showTab(int index)
    {
// Save search text before rebuild
        String savedSearch = (searchField != null && index == 1) ? searchField.getText() : "";

        tabContentPanel.removeAll();
        if (!isRefreshing)
        {
            currentOpenSearchDetail = null;
            currentOpenWatchlistDetail = null;
            currentOpenBankDetail = null;
            currentOpenSearchRow = null;
            currentOpenWatchlistRow = null;
            currentOpenBankRow = null;
            selectedItemName = null;
            selectedWatchlistItemName = null;
            selectedBankItemName = null;
            searchReopenAction = null;
            watchlistReopenAction = null;
            bankReopenAction = null;
            graphWasOpen = false;
        }
        livePriceLabels.clear();
        liveDeltaLabels.clear();
        liveGpChangeLabels.clear();
        switch (index)
        {
            case 0: tabContentPanel.add(buildWatchlistTab(), BorderLayout.CENTER); break;
            case 1: tabContentPanel.add(buildSearchTab(), BorderLayout.CENTER); break;
            case 2: tabContentPanel.add(buildBankTab(), BorderLayout.CENTER); break;
        }
        tabContentPanel.revalidate();
        tabContentPanel.repaint();

        // Restore search text after rebuild
        if (!savedSearch.isEmpty() && searchField != null && index == 1)
        {
            suppressSearchChange = true;
            searchField.setText(savedSearch);
            suppressSearchChange = false;
            onSearchChanged(savedSearch);
        }
    }
    private void refreshOpenDetail()
    {
        if (liveOpenItemId == -1 || liveOpenItemData == null) return;

        PriceData pd = priceCache.get(liveOpenItemId);
        if (pd == null) return;

        String[] item = liveOpenItemData;
        long mid = pd.getMid();

        // Update header price label
        if (liveHeaderPriceLabel != null)
        {
            liveHeaderPriceLabel.setText(formatFullPrice(String.valueOf(mid)) + " gp");
        }

        checkPriceAlerts();

// Update compacted item row price labels
        for (java.util.Map.Entry<Integer, JLabel> entry : livePriceLabels.entrySet())
        {
            int id = entry.getKey();
            JLabel label = entry.getValue();
            PriceData rowPd = priceCache.get(id);
            if (rowPd != null && label != null)
            {
                long rowMid = rowPd.getMid();
                javax.swing.SwingUtilities.invokeLater(() -> label.setText(formatPrice(String.valueOf(rowMid)) + " gp"));
            }
        }

        // Update compacted item row delta labels
        for (java.util.Map.Entry<Integer, JLabel> entry : liveDeltaLabels.entrySet())
        {
            int id = entry.getKey();
            JLabel label = entry.getValue();
            PriceData rowPd = priceCache.get(id);
            if (rowPd != null && label != null)
            {
                long currentPrice = rowPd.getMid();
                long historicalPrice = 0;
                if (activeTimeFrame.equals("1H")) historicalPrice = plugin.getAvgPrice1h().getOrDefault(id, 0L);
                else if (activeTimeFrame.equals("6H")) historicalPrice = plugin.getAvgPrice6h().getOrDefault(id, 0L);
                else if (activeTimeFrame.equals("24H")) historicalPrice = plugin.getAvgPrice24h().getOrDefault(id, 0L);
                if (historicalPrice > 0 && currentPrice > 0)
                {
                    double pct = ((double)(currentPrice - historicalPrice) / historicalPrice) * 100.0;
                    String deltaStr = String.format("%+.2f%%", pct);
                    boolean isUp = pct > 0;
                    boolean isDown = pct < 0;
                    Color color = isUp ? GREEN_UP : isDown ? RED_DOWN : TAB_INACTIVE;
                    javax.swing.SwingUtilities.invokeLater(() -> {
                        label.setText("(" + deltaStr + ")");
                        label.setForeground(color);
                    });
                }
            }
        }

// Update compacted item row gp change labels
        for (java.util.Map.Entry<Integer, JLabel> entry : liveGpChangeLabels.entrySet())
        {
            int id = entry.getKey();
            JLabel label = entry.getValue();
            PriceData rowPd = priceCache.get(id);
            if (rowPd != null && label != null)
            {
                long currentPrice = rowPd.getMid();
                long historicalPrice = 0;
                if (activeTimeFrame.equals("1H")) historicalPrice = plugin.getAvgPrice1h().getOrDefault(id, 0L);
                else if (activeTimeFrame.equals("6H")) historicalPrice = plugin.getAvgPrice6h().getOrDefault(id, 0L);
                else if (activeTimeFrame.equals("24H")) historicalPrice = plugin.getAvgPrice24h().getOrDefault(id, 0L);
                if (historicalPrice > 0 && currentPrice > 0)
                {
                    long gpDiff = currentPrice - historicalPrice;
                    boolean isUp = gpDiff > 0;
                    boolean isDown = gpDiff < 0;
                    String gpStr = (isUp ? "+" : isDown ? "-" : "") + formatPrice(String.valueOf(Math.abs(gpDiff))) + " gp";
                    Color color = isUp ? GREEN_UP : isDown ? RED_DOWN : TAB_INACTIVE;
                    javax.swing.SwingUtilities.invokeLater(() -> {
                        label.setText(gpStr);
                        label.setForeground(color);
                    });
                }
            }
        }

// Update Buy Price box
        if (liveBuyPriceValueLabel != null)
        {
            String buyPriceDisplay = pd.high <= 0 ? "?" : formatFullPrice(String.valueOf(pd.high)) + " gp";
            liveBuyPriceValueLabel.setText(buyPriceDisplay);
        }
        if (liveBuyPriceHeaderLabel != null)
        {
            String buyTimeStr = pd.getBuyTimeSince();
            String buyPriceLabel = "BUY PRICE" + (buyTimeStr.equals("unknown") ? "" : "  ·  " + buyTimeStr);
            liveBuyPriceHeaderLabel.setText(buyPriceLabel);
        }

// Update Sell Price box
        if (liveSellPriceValueLabel != null)
        {
            String sellPriceDisplay = pd.low <= 0 ? "?" : formatFullPrice(String.valueOf(pd.low)) + " gp";
            liveSellPriceValueLabel.setText(sellPriceDisplay);
        }
        if (liveSellPriceHeaderLabel != null)
        {
            String sellTimeStr = pd.getSellTimeSince();
            String sellPriceLabel = "SELL PRICE" + (sellTimeStr.equals("unknown") ? "" : "  ·  " + sellTimeStr);
            liveSellPriceHeaderLabel.setText(sellPriceLabel);
        }

// Update floating stats panel live (Margin, Profit, ROI only — Volume is static)
        if (activeStatsFloatPanel != null && liveOpenItemId != -1) {
            long liveTax = calculateGeTax(pd.high);
            long liveMargin = pd.high - pd.low - liveTax;
            Integer liveBuyLimit = itemLimits.get(liveOpenItemId);
            long liveProfitAtLimit = liveBuyLimit != null ? liveMargin * liveBuyLimit : 0;
            Long liveDailyVol = volumeCache.get(liveOpenItemId);
            long liveMarginVolume = liveDailyVol != null ? liveMargin * liveDailyVol : 0;
            double liveRoi = pd.low > 0 ? ((double) liveMargin / pd.low) * 100.0 : 0;
            if (liveFloatMarginLabel != null) {
                String mStr = (liveMargin >= 0 ? "+" : "") + formatFullPrice(String.valueOf(liveMargin)) + " gp";
                liveFloatMarginLabel.setText(mStr);
                liveFloatMarginLabel.setForeground(liveMargin >= 0 ? new Color(109, 184, 109) : new Color(192, 57, 43));
            }
            if (liveFloatProfitLabel != null) {
                String pStr = liveBuyLimit != null ? (liveProfitAtLimit >= 0 ? "+" : "") + formatFullPrice(String.valueOf(liveProfitAtLimit)) + " gp" : "?";
                liveFloatProfitLabel.setText(pStr);
                liveFloatProfitLabel.setForeground(liveProfitAtLimit >= 0 ? new Color(109, 184, 109) : new Color(192, 57, 43));
            }
            if (liveFloatMarginVolLabel != null) {
                String mvStr = liveDailyVol != null ? formatFullPrice(String.valueOf(liveMarginVolume)) + " gp" : "?";
                liveFloatMarginVolLabel.setText(mvStr);
                liveFloatMarginVolLabel.setForeground(liveMarginVolume >= 0 ? new Color(109, 184, 109) : new Color(192, 57, 43));
            }
            if (liveFloatRoiLabel != null) {
                liveFloatRoiLabel.setText(String.format("%.2f%%", liveRoi));
            }
        }

// Repaint graph if open
        if (liveGraphPanel != null)
        {
            liveGraphPanel.repaint();
        }
    }

