    private void updateSearchResults(String query) {
        searchResultsPanel.removeAll();

        List<String[]> results = new ArrayList<>();

        if (!nameToId.isEmpty() && !priceCache.isEmpty()) {
            // Use live data
            for (Map.Entry<String, Integer> entry : nameToId.entrySet()) {
                if (entry.getKey().contains(query)) {
                    int id = entry.getValue();
                    PriceData pd = priceCache.get(id);
                    if (pd != null && pd.getMid() > 0) {
                        String name = entry.getKey();
// Capitalize first letter of each word
                        String[] words = name.split(" ");
                        StringBuilder sb = new StringBuilder();
                        for (String word : words) {
                            if (word.length() > 0)
                                sb.append(Character.toUpperCase(word.charAt(0)))
                                        .append(word.substring(1)).append(" ");
                        }
                        String displayName = sb.toString().trim();
                        String[] fullItem = buildItemDataFromCache(displayName);
                        if (fullItem != null) results.add(fullItem);
                    }
                }
            }

            // Sort alphabetically
            results.sort((a, b) -> a[0].compareTo(b[0]));
            // Limit to 50 results
            if (results.size() > 50) results = results.subList(0, 50);
        } else {
            // Data still loading
            searchResultsPanel.removeAll();
            JLabel loading = new JLabel("⟳ Loading prices...");
            loading.setForeground(TAB_INACTIVE);
            loading.setFont(new Font("Monospaced", Font.PLAIN, FONT_META));
            loading.setBorder(new EmptyBorder(8, 7, 8, 7));
            loading.setAlignmentX(Component.LEFT_ALIGNMENT);
            searchResultsPanel.add(loading);
            searchResultsPanel.revalidate();
            searchResultsPanel.repaint();
            return;
        }

        if (results.isEmpty()) {
            JLabel noResults = new JLabel("No results found");
            noResults.setForeground(TEXT_DIM);
            noResults.setFont(new Font("Monospaced", Font.PLAIN, FONT_META));
            noResults.setBorder(new EmptyBorder(8, 7, 8, 7));
            noResults.setAlignmentX(Component.LEFT_ALIGNMENT);
            searchResultsPanel.add(noResults);
        } else {
            int searchIndex = 0;
            for (String[] item : results) {
                searchResultsPanel.add(buildSearchItemBlock(item, searchIndex++));
            }
        }
        searchResultsPanel.add(Box.createVerticalGlue());
        searchResultsPanel.revalidate();
        searchResultsPanel.repaint();
        scheduleRepaint(searchResultsPanel);
    }

    private JPanel buildSearchItemBlock(String[] item, int index)
    {
        String name = item[0];
        String price = item[1];
        String buyQty = item[3];
        String sellQty = item[4];
        String delta = item[5];
        String limit = item.length > 6 ? item[6] : "?";
        String gpChange = item.length > 7 ? item[7] : "0";

        boolean isUp = delta.startsWith("+");
        boolean isDown = delta.startsWith("-");
        Color rowBg = (index % 2 == 0) ? BG_DARK : new Color(20, 18, 19);

        final float[] rowHoverProgress = {0f};
        final javax.swing.Timer[] rowHoverAnimTimer = {null};

        JPanel block = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                java.awt.Insets in = getInsets();
                int fx = in.left, fy = in.top;
                int fw = getWidth() - in.left - in.right;
                int fh = getHeight() - in.top - in.bottom;
                java.awt.geom.RoundRectangle2D roundedShape = new java.awt.geom.RoundRectangle2D.Float(
                        fx, fy, fw, fh, RADIUS_CARD * 2, RADIUS_CARD * 2);
                Boolean expandedForFill = (Boolean) getClientProperty(ROW_EXPANDED_GOLD_KEY);
                Color fillColor = Boolean.TRUE.equals(expandedForFill) ? new Color(29, 27, 27) : lerpColor(rowBg, BG_ROW_HOVER, rowHoverProgress[0]);
                g2.setColor(fillColor);
                g2.fill(roundedShape);
                g2.dispose();
            }
            @Override
            public void paint(Graphics g) {
                super.paint(g);
                Boolean isExpanded = (Boolean) getClientProperty(ROW_EXPANDED_GOLD_KEY);
                if (!Boolean.TRUE.equals(isExpanded)) return;
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                java.awt.geom.RoundRectangle2D outline = new java.awt.geom.RoundRectangle2D.Float(
                        0, 0, getWidth() - 1, getHeight() - 1, RADIUS_CARD * 2, RADIUS_CARD * 2);
                g2.setColor(GOLD);
                g2.setStroke(new java.awt.BasicStroke(1));
                g2.draw(outline);
                g2.dispose();
            }
        };
        block.setOpaque(false);
        block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
        block.setBackground(rowBg);
        block.setAlignmentX(Component.LEFT_ALIGNMENT);
        block.setBorder(new EmptyBorder(1, 1, 1, 1));
        block.setMaximumSize(new Dimension(Integer.MAX_VALUE, 800));

        JPanel row = new JPanel(new BorderLayout()) {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                int w = getWidth();
                int h = getHeight();
                int r = RADIUS_CARD * 2;
                java.awt.Container p = getParent();
                Boolean expanded = p instanceof JComponent ? (Boolean) ((JComponent) p).getClientProperty(ROW_EXPANDED_GOLD_KEY) : null;
                java.awt.Shape shape;
                if (Boolean.TRUE.equals(expanded)) {
                    java.awt.geom.Path2D.Float path = new java.awt.geom.Path2D.Float();
                    path.moveTo(0, h);
                    path.lineTo(0, r / 2.0);
                    path.quadTo(0, 0, r / 2.0, 0);
                    path.lineTo(w - r / 2.0, 0);
                    path.quadTo(w, 0, w, r / 2.0);
                    path.lineTo(w, h);
                    path.closePath();
                    shape = path;
                } else {
                    shape = new java.awt.geom.RoundRectangle2D.Float(0, 0, w, h, r, r);
                }
                Color rowFillColor = Boolean.TRUE.equals(expanded) ? new Color(29, 27, 27) : lerpColor(rowBg, BG_ROW_HOVER, rowHoverProgress[0]);
                g2.setColor(rowFillColor);
                g2.fill(shape);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        row.setOpaque(false);
        row.setBackground(rowBg);
        row.setBorder(new EmptyBorder(1, 0, 0, 0));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 68));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        row.putClientProperty("geCompanionRowHoverProgress", rowHoverProgress);
        row.putClientProperty("geCompanionRowHoverAnimTimer", rowHoverAnimTimer);

        JPanel iconPanel = new JPanel(new java.awt.GridBagLayout()) {
            @Override
            public void paint(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                java.awt.geom.RoundRectangle2D roundedShape = new java.awt.geom.RoundRectangle2D.Float(
