                heroLabelAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                    heroLabelHoverProgress[0] = Math.max(0f, heroLabelHoverProgress[0] - 0.15f);
                    heroLabel.setForeground(lerpColor(TEXT_SECONDARY, GOLD, heroLabelHoverProgress[0]));
