            losersAccent.setMaximumSize(new Dimension(Integer.MAX_VALUE, 2));
            losersAccent.setAlignmentX(Component.LEFT_ALIGNMENT);
            listPanel.add(losersAccent);

            int losersCount = Math.min(config.losersCount(), losers.size());
            for (int i = 0; i < losersCount; i++) {
                displayedGainersLosers.add(losers.get(i)[0]);
                listPanel.add(buildBankItemBlock(losers.get(i), true, i, variantOwned));
            }

// All Items — collapsible
            JLabel allLabel = new JLabel((bankAllItemsCollapsed ? "≡ All Bank Items ▶" : "≡ All Bank Items ▼"));
            allLabel.setForeground(TAB_INACTIVE);
            allLabel.setToolTipText("<html>All bank items priced above 10,000 gp each,<br>with a total stack value above the threshold set in plugin settings.</html>");
            allLabel.setFont(new Font("Monospaced", Font.PLAIN, FONT_SECTION));
            allLabel.setBorder(new EmptyBorder(6, 7, 2, 7));
            allLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
            allLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            final float[] allLabelHoverProgress = {0f};
            final javax.swing.Timer[] allLabelAnimTimer = {null};
            allLabel.addMouseListener(new MouseAdapter()
            {
                public void mouseClicked(MouseEvent e)
                {
                    bankAllItemsCollapsed = !bankAllItemsCollapsed;
                    showTab(2);
                }
                public void mouseEntered(MouseEvent e) {
                    if (allLabelAnimTimer[0] != null) allLabelAnimTimer[0].stop();
                    allLabelAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                        allLabelHoverProgress[0] = Math.min(1f, allLabelHoverProgress[0] + 0.15f);
                        allLabel.setForeground(lerpColor(TAB_INACTIVE, TEXT_PRIMARY, allLabelHoverProgress[0]));
                        if (allLabelHoverProgress[0] >= 1f) allLabelAnimTimer[0].stop();
                    });
                    allLabelAnimTimer[0].start();
                }
                public void mouseExited(MouseEvent e) {
                    if (allLabelAnimTimer[0] != null) allLabelAnimTimer[0].stop();
                    allLabelAnimTimer[0] = new javax.swing.Timer(16, ev -> {
                        allLabelHoverProgress[0] = Math.max(0f, allLabelHoverProgress[0] - 0.15f);
                        allLabel.setForeground(lerpColor(TAB_INACTIVE, TEXT_PRIMARY, allLabelHoverProgress[0]));
                        if (allLabelHoverProgress[0] <= 0f) allLabelAnimTimer[0].stop();
                    });
                    allLabelAnimTimer[0].start();
                }
            });
            listPanel.add(allLabel);
// Bank search bar — always visible
            JPanel bankSearchWrap = new JPanel(new BorderLayout());
            bankSearchWrap.setBackground(new Color(20, 18, 19));
            bankSearchWrap.setBorder(new EmptyBorder(4, 6, 4, 6));
            bankSearchWrap.setAlignmentX(Component.LEFT_ALIGNMENT);
            bankSearchWrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
            bankSearchWrap.setMinimumSize(new Dimension(0, 34));
            bankSearchWrap.setPreferredSize(new Dimension(214, 34));

            JTextField bankSearchField = new JTextField();
            bankSearchField.setBackground(new Color(14, 12, 13));
            bankSearchField.setForeground(TEXT_PRIMARY);
            bankSearchField.setCaretColor(TEXT_PRIMARY);
            bankSearchField.setBorder(BorderFactory.createCompoundBorder(
                    createRoundedLineBorder(new Color(58, 53, 48), 1, RADIUS_BUTTON),
                    new EmptyBorder(3, 5, 3, 5)
            ));
            bankSearchField.setFont(new Font("Monospaced", Font.PLAIN, FONT_META));
            bankSearchField.setPreferredSize(new Dimension(190, 24));
            bankSearchField.setMaximumSize(new Dimension(190, 24));
            bankSearchField.setMinimumSize(new Dimension(190, 24));
            bankSearchWrap.add(bankSearchField, BorderLayout.CENTER);
            listPanel.add(bankSearchWrap);

            JPanel bankResultsPanel = new JPanel();
            bankResultsPanel.setLayout(new BoxLayout(bankResultsPanel, BoxLayout.Y_AXIS));
            bankResultsPanel.setBackground(BG_DARK);
            bankResultsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
            bankResultsPanel.setMinimumSize(new java.awt.Dimension(0, 0));
            bankResultsPanel.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

            final java.util.List<String[]> finalBankItems = new java.util.ArrayList<>(allBankItems);

            Runnable updateBankSearch = () -> {
                bankResultsPanel.removeAll();
                String query = bankSearchField.getText().trim().toLowerCase();
                boolean hasQuery = !query.isEmpty();

                if (!bankAllItemsCollapsed || hasQuery) {
                    java.util.List<String[]> filtered = hasQuery ?
                            finalBankItems.stream()
                            .filter(i -> i[0].toLowerCase().contains(query))
                            .collect(java.util.stream.Collectors.toList()) :
                            finalBankItems;

                    if (filtered.isEmpty() && hasQuery) {
                        JLabel noResults = new JLabel("No items found in your bank");
                        noResults.setForeground(TEXT_DIM);
                        noResults.setFont(new Font("Monospaced", Font.PLAIN, FONT_META));
                        noResults.setBorder(new EmptyBorder(8, 7, 4, 7));
                        noResults.setAlignmentX(Component.LEFT_ALIGNMENT);
                        bankResultsPanel.add(noResults);
                    } else {
                        int bankAllIndex = 0;
                        for (String[] i : filtered)
                            bankResultsPanel.add(buildBankItemBlock(i, false, bankAllIndex++, variantOwned));
                    }
                }
                bankResultsPanel.revalidate();
                bankResultsPanel.repaint();
            };

            bankSearchField.addFocusListener(new FocusAdapter()
            {
                public void focusGained(FocusEvent e)
                {
                    bankSearchField.setBorder(BorderFactory.createCompoundBorder(
                            createRoundedLineBorder(GOLD, 1, RADIUS_BUTTON),
                            new EmptyBorder(3, 5, 3, 5)
                    ));
                }
                public void focusLost(FocusEvent e)
                {
                    bankSearchField.setBorder(BorderFactory.createCompoundBorder(
                            createRoundedLineBorder(new Color(58, 53, 48), 1, RADIUS_BUTTON),
                            new EmptyBorder(3, 5, 3, 5)
                    ));
                }
            });

            bankSearchField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
            {
                public void insertUpdate(javax.swing.event.DocumentEvent e) { SwingUtilities.invokeLater(updateBankSearch); }
                public void removeUpdate(javax.swing.event.DocumentEvent e) { SwingUtilities.invokeLater(updateBankSearch); }
                public void changedUpdate(javax.swing.event.DocumentEvent e) { SwingUtilities.invokeLater(updateBankSearch); }
            });

            updateBankSearch.run();
            listPanel.add(bankResultsPanel);
        }

        panel.add(listPanel, BorderLayout.CENTER);
        scheduleRepaint(listPanel);
        return panel;
    }

    private JPanel buildBankItemBlock(String[] item, boolean colorCode, int index, java.util.Map<String, java.util.List<String>> variantOwned)
    {
        String name = item[0];
        String price = item[1];
        String delta = item[5];
        String gpChange = item.length > 7 ? item[7] : "0 gp";
        boolean isVariant = item.length > 13 && Boolean.parseBoolean(item[13]);
        String originalBankName = item.length > 14 ? item[14] : null;
// Get all owned variants for this tradeable base
        java.util.List<String> ownedVariants = variantOwned != null ? variantOwned.get(name) : null;

        boolean isUp = delta.startsWith("+");
        boolean isDown = delta.startsWith("-");

        Color borderColor = colorCode && isUp ? new Color(0, 180, 0) : colorCode && isDown ? new Color(200, 0, 0) : new Color(80, 75, 70);
        Color bgColor = (index % 2 == 0) ? BG_DARK : new Color(20, 18, 19);

        final float[] rowHoverProgress = {0f};
        final javax.swing.Timer[] rowHoverAnimTimer = {null};

        JPanel block = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                // When expanded (row is showing its gold selection outline), square off the bottom corners
                // to match row's shape - otherwise this panel's own rounded bottom corners peek out from
                // underneath row's now-square bottom edge, leaving a sliver of the gradient/accent visible.
                // Fill only within our own reserved insets, so the 1px margin reserved for the gold
                // outline doesn't expose an extra ring of background/gradient around row when collapsed.
                java.awt.Insets in = getInsets();
                int fx = in.left, fy = in.top;
                int fw = getWidth() - in.left - in.right;
                int fh = getHeight() - in.top - in.bottom;
                Boolean blockExpanded = (Boolean) getClientProperty(ROW_EXPANDED_GOLD_KEY);
                java.awt.Shape roundedShape;
                if (Boolean.TRUE.equals(blockExpanded)) {
                    roundedShape = new java.awt.geom.RoundRectangle2D.Float(
                            fx, fy, fw, fh, RADIUS_CARD * 2, RADIUS_CARD * 2);
                } else {
                    roundedShape = new java.awt.geom.RoundRectangle2D.Float(
                            fx, fy, fw, fh, RADIUS_CARD * 2, RADIUS_CARD * 2);
                }
                Color fillColor = Boolean.TRUE.equals(blockExpanded) ? new Color(29, 27, 27) : lerpColor(bgColor, BG_ROW_HOVER, rowHoverProgress[0]);
                g2.setColor(fillColor);
                g2.fill(roundedShape);
                if (colorCode && (isUp || isDown))
                {
                    java.awt.Shape oldClip = g2.getClip();
                    g2.clip(roundedShape);
                    Color gradColor = isUp ? new Color(0, 180, 0, 220) : new Color(200, 0, 0, 220);
                    GradientPaint gp = new GradientPaint(0, 0, gradColor, getWidth() * 0.75f, 0, new Color(0, 0, 0, 0));
                    g2.setPaint(gp);
                    g2.fillRect(0, 0, getWidth(), getHeight());
                    g2.setClip(oldClip);
                }
                g2.dispose();
            }
            @Override
            public void paint(Graphics g)
            {
                super.paint(g);

                Boolean isExpanded = (Boolean) getClientProperty(ROW_EXPANDED_GOLD_KEY);
                if (!Boolean.TRUE.equals(isExpanded)) return;

                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(
                        java.awt.RenderingHints.KEY_ANTIALIASING,
                        java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

                java.awt.geom.RoundRectangle2D outline =
                        new java.awt.geom.RoundRectangle2D.Float(
                                0, 0,
                                getWidth() - 1,
                                getHeight() - 1,
                                RADIUS_CARD * 2,
                                RADIUS_CARD * 2);

                g2.setColor(GOLD);
                g2.setStroke(new java.awt.BasicStroke(1));
                g2.draw(outline);
                g2.dispose();
            }
        };
        block.setOpaque(false);
        block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
        block.setBackground(bgColor);
        block.setAlignmentX(Component.LEFT_ALIGNMENT);
        block.setBorder(new EmptyBorder(1, 1, 1, 1));
        block.setMaximumSize(new Dimension(Integer.MAX_VALUE, 800));

        JPanel row = new JPanel(new BorderLayout()) {
            @Override
            protected void paintComponent(Graphics g) {
                // Bottom corners round when collapsed (row IS the whole card), square when expanded
                // (flat seam against the detail panel below). See technique notes for why always-square
                // was wrong for the collapsed case.
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                int w = getWidth();
                int h = getHeight();
                int r = RADIUS_CARD * 2;
                java.awt.Container p = getParent();
                Boolean expanded = p instanceof JComponent ? (Boolean) ((JComponent) p).getClientProperty(ROW_EXPANDED_GOLD_KEY) : null;
                java.awt.Shape shape;
                if (Boolean.TRUE.equals(expanded)) {
                    java.awt.geom.Path2D.Float path = new java.awt.geom.Path2D.Float();
                    path.moveTo(0, h);
                    path.lineTo(0, r / 2.0);
                    path.quadTo(0, 0, r / 2.0, 0);
                    path.lineTo(w - r / 2.0, 0);
                    path.quadTo(w, 0, w, r / 2.0);
                    path.lineTo(w, h);
                    path.closePath();
                    shape = path;
                } else {
                    shape = new java.awt.geom.RoundRectangle2D.Float(0, 0, w, h, r, r);
                }
                Color rowFillColor = Boolean.TRUE.equals(expanded) ? new Color(29, 27, 27) : lerpColor(bgColor, BG_ROW_HOVER, rowHoverProgress[0]);
                g2.setColor(rowFillColor);
                g2.fill(shape);
                g2.dispose();
                super.paintComponent(g);
            }
            @Override
            protected void paintBorder(Graphics g) {
                Boolean expandedGold = (Boolean) getClientProperty(ROW_EXPANDED_GOLD_KEY);
                if (Boolean.TRUE.equals(expandedGold)) return;
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                Color accent = (Color) getClientProperty(ROW_ACCENT_COLOR_KEY);
                if (accent != null) {
                    java.awt.geom.RoundRectangle2D clipShape = new java.awt.geom.RoundRectangle2D.Float(
                            0, 0, getWidth(), getHeight(), RADIUS_CARD * 2, RADIUS_CARD * 2);
                    g2.clip(clipShape);
                    g2.setColor(accent);
                    g2.fillRect(0, 0, 4, getHeight());
                }
                g2.dispose();
            }
        };
        row.putClientProperty(ROW_ACCENT_COLOR_KEY, borderColor);
        row.putClientProperty(ROW_EXPANDED_GOLD_KEY, false);
        block.putClientProperty(ROW_EXPANDED_GOLD_KEY, false);
        row.setOpaque(false);
        row.setBackground(bgColor);
        row.setBorder(new EmptyBorder(1, 4, 0, 0));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 68));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        row.putClientProperty("geCompanionRowHoverProgress", rowHoverProgress);
        row.putClientProperty("geCompanionRowHoverAnimTimer", rowHoverAnimTimer);
        JPanel iconPanel = new JPanel() {
            @Override
            public void paint(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                // Clip everything (background, sprite, badge) to a rounded shape - visual clipping only,
                // never modifies the underlying sprite image data.
                java.awt.geom.RoundRectangle2D roundedShape = new java.awt.geom.RoundRectangle2D.Float(
                        0, 0, getWidth(), getHeight(), RADIUS_ICON * 2, RADIUS_ICON * 2);
                g2.clip(roundedShape);
                super.paint(g2);
                g2.dispose();
            }
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                if (isVariant) {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setFont(new Font("Monospaced", Font.BOLD, 10));
                    g2.setColor(GOLD);
                    FontMetrics fm = g2.getFontMetrics();
                    String badge = "*";
                    int bw = fm.stringWidth(badge);
                    g2.drawString(badge, getWidth() - bw - 2, fm.getAscent() + 1);
                    g2.dispose();
                }
            }
        };
        iconPanel.setPreferredSize(new Dimension(42, 42));
        iconPanel.setBackground(new Color(14, 12, 13));
        iconPanel.setOpaque(true);
        iconPanel.setBorder(createRoundedLineBorder(colorCode && isUp ? new Color(0, 100, 0) : colorCode && isDown ? new Color(100, 0, 0) : new Color(42, 37, 40), 1, RADIUS_ICON));

        Integer bankItemId = nameToId.get(name.toLowerCase()
                .replace('\u2019', '\'')
                .replace('\u2018', '\''));
        if (bankItemId == null) bankItemId = nameToId.get(name.toLowerCase());
        if (bankItemId != null)
        {
            loadIconAsync(bankItemId, iconPanel, bgColor);
        }

        JPanel iconWrapper = new JPanel(new java.awt.GridBagLayout());
        iconWrapper.setBackground(bgColor);
        iconWrapper.setOpaque(false);
        iconWrapper.add(iconPanel);
        if (isVariant) {
            Integer origId = item.length > 12 ? Integer.parseInt(item[12]) : null;
            if (origId != null && originalBankName != null && !originalBankName.isEmpty()) {
                final int popupBaseId = origId;
                final java.util.List<String> popupOwnedVariants = (ownedVariants != null && !ownedVariants.isEmpty())
                        ? new java.util.ArrayList<>(ownedVariants)
                        : java.util.Collections.singletonList(originalBankName);
                iconWrapper.addMouseListener(new java.awt.event.MouseAdapter() {
                    @Override
                    public void mouseEntered(java.awt.event.MouseEvent e) {
                        // Ignore stray mouseEntered events fired by Swing reflowing this row into place
                        // under a stationary cursor during/right after a rebuild - require a genuine hover.
                        if (suppressVariantPopupActivation) {
                            return;
                        }
                        showVariantPopup(iconWrapper, popupBaseId, popupOwnedVariants);
                    }
                    @Override
                    public void mouseExited(java.awt.event.MouseEvent e) {
                        hideVariantPopup();
                    }
                });
            }
        } else {
            iconWrapper.addMouseListener(new java.awt.event.MouseAdapter() {
                @Override
                public void mouseEntered(java.awt.event.MouseEvent e) {
                    // Fallback: if a non-variant row reflows under a stationary cursor after a rebuild,
                    // make sure any lingering variant popup from the previous row is cleared.
                    hideVariantPopup();
                }
            });
            iconWrapper.setToolTipText(name);
        }
        row.add(iconWrapper, BorderLayout.WEST);

        JPanel info = new JPanel();
        info.setLayout(new BoxLayout(info, BoxLayout.Y_AXIS));
        info.setBackground(bgColor);
        info.setOpaque(false);
        info.setBorder(new EmptyBorder(5, 7, 8, 0));

        MarqueeLabel nameLabel = new MarqueeLabel(name, TEXT_PRIMARY, new Font("Monospaced", Font.PLAIN, FONT_ITEM_NAME), 360, 20);

        JLabel priceLabel = new JLabel(formatPrice(price) + " gp");
        priceLabel.setForeground(PRICE_GOLD);
        priceLabel.setFont(new Font("Monospaced", Font.PLAIN, FONT_PRICE));
        if (bankItemId != null) livePriceLabels.put(bankItemId, priceLabel);

        JLabel deltaLabel = new JLabel("(" + delta + "%)");
        deltaLabel.setForeground(isUp ? GREEN_UP : isDown ? RED_DOWN : TAB_INACTIVE);
        if (bankItemId != null) liveDeltaLabels.put(bankItemId, deltaLabel);
        deltaLabel.setFont(new Font("Monospaced", Font.PLAIN, FONT_LIMIT));
        deltaLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel gpChangeLabel = new JLabel(gpChange);
        gpChangeLabel.setForeground(isUp ? GREEN_UP : isDown ? RED_DOWN : TAB_INACTIVE);
        gpChangeLabel.setFont(new Font("Monospaced", Font.PLAIN, FONT_DELTA));
        if (bankItemId != null) liveGpChangeLabels.put(bankItemId, gpChangeLabel);

        JPanel deltaRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        deltaRow.setBackground(bgColor);
        deltaRow.setOpaque(false);
        deltaRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        deltaRow.add(gpChangeLabel);
        deltaRow.add(Box.createHorizontalStrut(4));
        deltaRow.add(deltaLabel);

        info.add(nameLabel);
        info.add(priceLabel);
        info.add(deltaRow);
        row.add(info, BorderLayout.CENTER);
        row.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) { nameLabel.startHoverDelay(); }
            @Override
            public void mouseExited(MouseEvent e) { nameLabel.stopAll(); }
            @Override
            public void mouseClicked(MouseEvent e) { nameLabel.stopAll(); }
        });

// Inline detail slot
        final JButton[] watchBtnRef = {null};
        JPanel detailSlot = new JPanel(new BorderLayout());
        detailSlot.setBackground(BG_DARK);
        detailSlot.setOpaque(false);
        detailSlot.setBorder(javax.swing.BorderFactory.createEmptyBorder());
        detailSlot.setAlignmentX(Component.LEFT_ALIGNMENT);

        javax.swing.JViewport detailViewport = new javax.swing.JViewport();
        detailViewport.setView(detailSlot);
        detailViewport.setOpaque(false); // TEMPORARY DIAGNOSTIC
        detailViewport.setVisible(false);
        detailViewport.setBorder(null);
        detailViewport.setAlignmentX(Component.LEFT_ALIGNMENT);

        row.addMouseListener(new MouseAdapter()
        {
            public void mouseClicked(MouseEvent e)
            {
                if (javax.swing.SwingUtilities.isRightMouseButton(e))
                {
                    javax.swing.JPopupMenu popup = new javax.swing.JPopupMenu();
                    boolean isWatched = pinnedItems.contains(item[0]);
                    javax.swing.JMenuItem watchItem = new javax.swing.JMenuItem(isWatched ? "- Unwatch" : "+ Watch");
                    watchItem.addActionListener(ev -> {
                        boolean nowWatched = !pinnedItems.contains(item[0]);
                        if (nowWatched) pinnedItems.add(item[0]);
                        else pinnedItems.remove(item[0]);
                        savePinnedItems();
                        if (activeStatsFloatPanel != null && activeStatsLayeredPane != null) {
                            activeStatsLayeredPane.remove(activeStatsFloatPanel);
                            activeStatsLayeredPane.repaint();
                            activeStatsFloatPanel = null;
                            activeStatsLayeredPane = null;
                        }
                        if (activeTab == 0) showTab(0);
                        JButton wb = watchBtnRef[0];
                        if (wb != null) {
                            wb.setText(nowWatched ? "✓ Watch" : "+ Watch");
                            wb.putClientProperty(FOOTER_BTN_GOLD_KEY, nowWatched);
                            wb.repaint();
                        }
                        watchItem.setText(nowWatched ? "- Unwatch" : "+ Watch");
                    });
                    popup.add(watchItem);
                    javax.swing.JMenuItem pricesItem = new javax.swing.JMenuItem("Prices ↗");
                    pricesItem.addActionListener(ev -> {
                        try {
                            int trackerItemId = item.length > 12 ? Integer.parseInt(item[12]) : -1;
                            net.runelite.client.util.LinkBrowser.browse("https://prices.runescape.wiki/osrs/item/" + trackerItemId);
                        } catch (Exception ex) { }
                    });
                    popup.add(pricesItem);
                    javax.swing.JMenuItem wikiItem = new javax.swing.JMenuItem("Wiki ↗");
                    wikiItem.addActionListener(ev -> {
                        try {
                            String wikiName = name.substring(0, 1).toUpperCase() + name.substring(1).toLowerCase().replace(" ", "_");
                            net.runelite.client.util.LinkBrowser.browse("https://oldschool.runescape.wiki/w/" + wikiName);
                        } catch (Exception ex) { }
                    });
                    popup.add(wikiItem);
                    popup.show(row, e.getX(), e.getY());
