    private void scheduleRepaint(JPanel panel)
    {
        int[] delays = {300, 600, 1000};
        for (int delay : delays)
        {
            javax.swing.Timer t = new javax.swing.Timer(delay, e -> {
                panel.revalidate();
                panel.repaint();
            });
            t.setRepeats(false);
            t.start();
        }
    }

